use sha2::{Digest, Sha256};
use std::time::Instant;
fn main() {
    let mut data = vec![17u8; 16 * 1024 * 1024];
    let mut samples = Vec::new();
    let mut digest = [0u8; 32];
    for sample in 0..12 {
        let before = Instant::now();
        for round in 0..16 {
            data[0] = round as u8;
            digest = Sha256::digest(std::hint::black_box(&data)).into();
        }
        if sample >= 2 { samples.push(before.elapsed().as_secs_f64()); }
    }
    let hex = digest.iter().map(|b| format!("{b:02x}")).collect::<String>();
    println!("{{\"accelerated\":{},\"bytes_per_sample\":{},\"samples_seconds\":{:?},\"last_digest\":\"{}\"}}",
        cfg!(feature = "accelerated"), data.len() * 16, samples, hex);
}
